import sys

class Employee:
    def __init__(self, name, emp_id, basic_salary):
        self.name = name
        self.id = emp_id
        self.basic_salary = basic_salary

class Engineer(Employee):
    def __init__(self, name, emp_id, basic_salary, bonus):
        super().__init__(name, emp_id, basic_salary)
        self.bonus = bonus

    def total_salary(self):
        return self.basic_salary + self.bonus

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    parts = line.split()
    name = parts[0]
    emp_id = int(parts[1])
    basic_salary = int(parts[2])
    bonus = int(parts[3])

    engineer = Engineer(name, emp_id, basic_salary, bonus)
    print(engineer.total_salary())

if __name__ == "__main__":
    main()
